import { Ledger, type Charge, type Status } from "./ledger.ts";

export type ChargeRequest = {
  idempotencyKey: string;
  currency: string;
  amount: number;
};

export type Provider = {
  createCharge(request: ChargeRequest): Promise<{ providerId: string; status: Status }>;
  pollCharge(providerId: string): Promise<Status>;
};

export async function charge(
  request: ChargeRequest,
  ledger: Ledger,
  provider: Provider,
): Promise<Status> {
  const existing = ledger.get(request.idempotencyKey);
  if (existing) return existing.status;

  const result = await provider.createCharge(request);
  const record: Charge = { ...request, ...result };
  ledger.save(record);
  return record.status;
}

