import { charge, type ChargeRequest, type Provider } from "./charge.ts";
import { Ledger, type Status } from "./ledger.ts";

export async function checkout(
  request: ChargeRequest,
  ledger: Ledger,
  provider: Provider,
): Promise<Status> {
  if (!/^[A-Z]{3}$/.test(request.currency)) throw new Error("Invalid currency");
  if (!Number.isFinite(request.amount) || request.amount <= 0) throw new Error("Invalid amount");
  return charge(request, ledger, provider);
}

