import assert from "node:assert/strict";
import test from "node:test";
import { checkout } from "./checkout.ts";
import { type ChargeRequest, type Provider } from "./charge.ts";
import { Ledger } from "./ledger.ts";
import { reconcile } from "./reconciliation.ts";

const request: ChargeRequest = { idempotencyKey: "idea-17", currency: "USD", amount: 12 };

test("one repeated request reuses the ledger result", async () => {
  const ledger = new Ledger();
  let providerCalls = 0;
  const provider: Provider = {
    async createCharge() {
      providerCalls += 1;
      return { providerId: "charge-17", status: "paid" };
    },
    async pollCharge() { return "paid"; },
  };

  assert.equal(await checkout(request, ledger, provider), "paid");
  assert.equal(await checkout(request, ledger, provider), "paid");
  assert.equal(providerCalls, 1);
  assert.equal(ledger.get(request.idempotencyKey)?.status, "paid");
});

test("one late success updates the same ledger", async () => {
  const ledger = new Ledger();
  let polledId: string | undefined;
  const provider: Provider = {
    async createCharge() { return { providerId: "charge-17", status: "pending" }; },
    async pollCharge(providerId) {
      polledId = providerId;
      return "paid";
    },
  };

  assert.equal(await checkout(request, ledger, provider), "pending");
  assert.equal(ledger.pending().length, 1);
  await reconcile(ledger, provider);
  assert.equal(polledId, "charge-17");
  assert.equal(ledger.get(request.idempotencyKey)?.status, "paid");
  assert.equal(ledger.pending().length, 0);
});

