// Synthetic, in-memory fixture. It is not a production payment implementation.
export type Status = "pending" | "paid" | "failed";
export type Charge = {
  idempotencyKey: string;
  currency: string;
  amount: number;
  providerId: string;
  status: Status;
};

export class Ledger {
  private charges = new Map<string, Charge>();

  get(key: string): Charge | undefined {
    return this.charges.get(key);
  }

  save(charge: Charge): void {
    this.charges.set(charge.idempotencyKey, charge);
  }

  pending(): Charge[] {
    return [...this.charges.values()].filter(charge => charge.status === "pending");
  }

  updateStatus(key: string, status: Status): void {
    const charge = this.charges.get(key);
    if (!charge) throw new Error("Missing charge");
    this.charges.set(key, { ...charge, status });
  }
}

