import { type Provider } from "./charge.ts";
import { Ledger } from "./ledger.ts";

export async function reconcile(ledger: Ledger, provider: Provider): Promise<void> {
  for (const charge of ledger.pending()) {
    const status = await provider.pollCharge(charge.providerId);
    ledger.updateStatus(charge.idempotencyKey, status);
  }
}
